using System;
using System.IO;
using System.Collections.Generic;
using UnityEngine;
using UnityEditor;
using CampaignDemo;
[InitializeOnLoad]
public static class MinimapAlertRuntimeVerification {
 static double start;static readonly List<string> checks=new List<string>();
 static MinimapAlertRuntimeVerification(){if(SessionState.GetBool("MinimapAlerts",false)){start=EditorApplication.timeSinceStartup;EditorApplication.update+=Poll;}}
 public static void Run(){MinimapInstaller.Run();SessionState.SetBool("MinimapAlerts",true);start=EditorApplication.timeSinceStartup;EditorApplication.update+=Poll;EditorApplication.isPlaying=true;}
 static void Check(bool ok,string label){if(!ok)throw new Exception(label);checks.Add("PASS "+label);}
 static BattleUnit Spawn(BattleWorld world,string role,string owner,Vector3 position){var g=UnityEngine.Object.Instantiate(AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Game/UnitLibrary/Prefabs/"+(owner=="A"?"Friendly":"Enemy")+"/"+role+"_Squad.prefab"));g.transform.position=position;var u=g.GetComponent<BattleUnit>();u.unitId=Guid.NewGuid().ToString("N");var mover=u.GetComponent<ArmyRoadMover>();mover.InitializeAt(world.setup.roadMap.Network,new RoadPoint(position.x,position.y),RoadRouteView.Create(g.transform,"test route",.06f,3,Color.cyan));u.GetComponent<ArmyFreeMarchMover>().Initialize(mover.Motor);u.GetComponent<ArmyFreeMarchMover>().BindMap(world.setup.freeMarchMap);world.RegisterUnit(u,mover);return u;}
 static void Poll(){try{
  if(EditorApplication.timeSinceStartup-start>90)throw new Exception("alert runtime timeout");if(!EditorApplication.isPlaying||Time.time<1)return;var mini=UnityEngine.Object.FindObjectOfType<TacticalMinimap>();var world=mini.world;if(!world.Initialized)return;var tracker=mini.GetComponent<MinimapAlertTracker>();var ai=world.GetComponent<BattleAIController>();ai.aiEnabled=false;
  foreach(var u in world.units){u.transform.position=u.ownerId=="A"?new Vector3(100,100):new Vector3(200,200);u.Motor?.Stop();}world.currentPlayer="A";var foot=Spawn(world,"Infantry","A",Vector3.zero);var car=Spawn(world,"TransportTruck","A",Vector3.right*3);var enemy=Spawn(world,"Infantry","B",Vector3.right*10);
  var fobj=new GameObject("alert fort");var fort=fobj.AddComponent<Fortification>();fort.ownerId="A";fort.Initialize(world.campaign.rules);world.campaign.combined.fortifications.Add(fort);
  var cobj=new GameObject("alert collector");var collector=cobj.AddComponent<ResourceCollector>();collector.ownerId="A";collector.Campaign=world.campaign;collector.Initialize();world.campaign.logistics.collectors.Add(collector);
  var depot=world.campaign.CreateDepot(Vector3.right*5,"A",100,false);var cityobj=new GameObject("alert city");var city=cityobj.AddComponent<RecoveryPoint>();city.ownerId="A";city.pointId=Guid.NewGuid().ToString("N");city.transform.position=Vector3.right*8;world.points=new[]{city};tracker.Sample();int initial=tracker.Alerts.Count;
  foot.Damage(.2f);car.Damage(1);fort.Damage(1);collector.Damage(1);tracker.Sample();Check(tracker.Alerts.Count==initial+4,"own troop vehicle fort collector each raise alerts");foot.Damage(.1f);tracker.Sample();Check(tracker.Alerts.Count==initial+4,"repeated attack merges same target alert");enemy.Damage(.1f);tracker.Sample();Check(tracker.Alerts.Count==initial+4,"enemy casualties do not trigger own alerts");depot.stock-=10;city.resourceStock-=10;tracker.Sample();Check(tracker.Alerts.Count==initial+4,"resource consumption is not treated as an attack");
  depot.capturingPlayer="B";depot.captureProgress=1;tracker.Sample();Check(tracker.Alerts.Count==initial+5,"warehouse contest raises alert");depot.ownerId="B";tracker.Sample();Check(tracker.Alerts.Count==initial+5,"warehouse ownership loss merges existing warning");
  enemy.transform.position=city.transform.position;world.Tick(1);tracker.Sample();Check(tracker.Alerts.Count==initial+6,"actual city capture attempt raises warning");
  world.setup.modes.EnterInspectionMode();var hud=mini.GetComponent<CampaignHUD>();hud.SelectUnit(foot);Check(mini.HighlightedUnit()==foot,"first army highlighted");hud.SelectUnit(car);Check(mini.HighlightedUnit()==car&&world.GetComponent<ArmySelection>().Selected==car.GetComponent<ArmyRoadMover>(),"second selection replaces first, no multiselect");mini.SetLayer(TacticalMinimap.LayerMode.Military);Check(mini.IncludesOwnUnit(foot)&&!mini.IncludesOwnUnit(car),"military filter includes army and excludes resource truck");mini.SetLayer(TacticalMinimap.LayerMode.Supply);Check(!mini.IncludesOwnUnit(foot)&&mini.IncludesOwnUnit(car),"supply filter includes resource truck and excludes army");Check(mini.HighlightedUnit()==car,"filter changes preserve selected army");mini.SetLayer(TacticalMinimap.LayerMode.All);hud.ClearSelection();Check(mini.HighlightedUnit()==null,"clear removes selected highlight");hud.SelectUnit(foot);foot.Eliminate();Check(mini.HighlightedUnit()==null,"dead selected army is not highlighted");
  mini.SetExpanded(false);car.Damage(1);tracker.Sample();Check(tracker.Alerts.Count>=initial+6,"alerts continue while minimap collapsed");world.SetPlayer("B");Check(tracker.Alerts.Count==0,"player change clears old side warnings immediately");mini.SetExpanded(true);
  File.WriteAllText("minimap-alert-runtime-verification.txt",checks.Count+" checks passed\n"+string.Join("\n",checks));Debug.Log("MINIMAP_ALERTS_VERIFIED "+checks.Count);SessionState.SetBool("MinimapAlerts",false);EditorApplication.update-=Poll;EditorApplication.Exit(0);
 }catch(Exception e){Debug.LogException(e);File.WriteAllText("minimap-alert-runtime-verification.txt",e+"\n"+string.Join("\n",checks));SessionState.SetBool("MinimapAlerts",false);EditorApplication.update-=Poll;EditorApplication.Exit(1);}}
}

